import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  FormControl,
  FormControlLabel,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Switch,
  TextField,
  Typography,
} from '@mui/material';
import { Link as RouterLink, Navigate, useLocation, useSearchParams } from 'react-router-dom';
import { reportingTabHref } from '../../constants/reportingTabs';
import ApiService from '../../services/api';
import {
  EXPORT_COMPLIANCE_GROUPS,
  EXPORT_COMPLIANCE_SECTIONS,
  EXPORT_RETIRED_SECTION_HREFS,
  unwrapComplianceHubPayload,
} from '../../constants/complianceHub';
import { useUrlSectionParam } from '../../hooks/useUrlSectionParam';
import { useOrchestrationEvents } from '../../hooks/useOrchestrationEvents';
import ComplianceTrackShell from './ComplianceTrackShell';
import ComplianceReadinessGrid from './ComplianceReadinessGrid';
import ComplianceReadinessGapPanel, { type ModuleGapBundle } from './ComplianceReadinessGapPanel';
import ComplianceJsonPanel from './ComplianceJsonPanel';
import ProductPcfWorkspace from './ProductPcfWorkspace';
import CbamInstallationGpsCapture from './CbamInstallationGpsCapture';
import GpsGeotaggedCapture from './GpsGeotaggedCapture';
import { BuyerPackReadiness } from './BuyerQuestionnaireGapPanel';
import BuyerPackReadinessPanel from './BuyerPackReadinessPanel';
import { type SupplierQuestionnaireRecord } from './BuyerPackQuestionnaireWizard';
import { type OrchestrationRunSummary } from './OrchestrationRunPanel';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { resolveTrackItemLabel, resolveHubSectionLabel } from '../../constants/complianceTrackLocale';
import ReportFilingReadinessBanner from '../reporting/ReportFilingReadinessBanner';
import CbamExportReadinessPanel from './CbamExportReadinessPanel';
import ComplianceOrchestrationHub from './ComplianceOrchestrationHub';
import ComplianceGapWorkspace from './ComplianceGapWorkspace';
import EudrPlotRegistryPanel from './EudrPlotRegistryPanel';
import EsrsEnvironmentalTopicsPanel from './EsrsEnvironmentalTopicsPanel';
import {
  EcovadisAssessmentPanel,
} from './ComplianceHubDepthCards';
import {
  isExportFormatClientAllowed,
  mapReportingDateRange,
  REPORTING_EXPORT_FORMATS,
} from '../../constants/reportingExports';

const EU_MEMBER_STATES = [
  'Austria', 'Belgium', 'Bulgaria', 'Croatia', 'Cyprus', 'Czechia', 'Denmark', 'Estonia', 'Finland', 'France',
  'Germany', 'Greece', 'Hungary', 'Ireland', 'Italy', 'Latvia', 'Lithuania', 'Luxembourg', 'Malta', 'Netherlands',
  'Poland', 'Portugal', 'Romania', 'Slovakia', 'Slovenia', 'Spain', 'Sweden'
];

const SECTION_IDS = EXPORT_COMPLIANCE_SECTIONS.map((s) => s.id);

type ExportComplianceTrackProps = {
  variant?: 'msme' | 'enterprise';
};

const CBAM_CATEGORIES = [
  'cement',
  'iron_steel',
  'aluminium',
  'fertilisers',
  'electricity',
  'hydrogen',
];

const ExportComplianceTrack: React.FC<ExportComplianceTrackProps> = ({ variant = 'msme' }) => {
  const isEnterprise = variant === 'enterprise';
  const location = useLocation();
  const [searchParams] = useSearchParams();
  useOrchestrationEvents(true);
  const { locale } = useReadinessLocale();
  const [section, setSection] = useUrlSectionParam('cbam', SECTION_IDS);
  const [period, setPeriod] = useState('annual');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [track, setTrack] = useState<Record<string, unknown> | null>(null);
  const [exportProfile, setExportProfile] = useState<Record<string, unknown>>({});
  const [saving, setSaving] = useState(false);
  const [exportPack, setExportPack] = useState<unknown>(null);
  const [cbamVerificationBusyId, setCbamVerificationBusyId] = useState<string | null>(null);
  const [cbamRegistryDownloading, setCbamRegistryDownloading] = useState(false);
  const [cbamRegistryFeedback, setCbamRegistryFeedback] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await ApiService.getComplianceExportTrack({ period });
      const data = unwrapComplianceHubPayload<Record<string, unknown>>(res);
      setTrack(data);
      if (data?.exportProfile) {
        setExportProfile(data.exportProfile as Record<string, unknown>);
      }
    } catch (e) {
      setTrack(null);
      setError(e instanceof Error ? e.message : 'Failed to load export compliance track');
    } finally {
      setLoading(false);
    }
  }, [period]);

  useEffect(() => {
    load();
  }, [load]);

  const modules = (track?.modules || {}) as Record<string, unknown>;
  const readiness = (track?.readiness || {}) as Record<string, string>;
  const packValidation = (track?.packValidation || {}) as Record<string, {
    valid?: boolean;
    missingFields?: string[];
    warnings?: string[];
    verificationRequired?: Array<{ field?: string; message?: string }>;
    framework?: string;
  }>;
  const buyerPackReadiness = (track?.buyerPackReadiness || null) as BuyerPackReadiness | null;
  const supplierQuestionnaires = (modules.supplierQuestionnaires || []) as SupplierQuestionnaireRecord[];
  const exportModuleScores = (track?.moduleScores || {}) as Record<string, number | null>;
  const moduleGapDetails = (track?.moduleGapDetails || {}) as Record<string, ModuleGapBundle>;
  const frameworkReadiness = (track?.frameworkReadiness || {}) as {
    cbam?: {
      reportReadinessLevel?: string;
      reportReadinessLabel?: string;
      readinessType?: string;
      blockedReasons?: string[];
      filingDisclaimer?: string;
    };
  };
  const cbamReadinessSnapshot = frameworkReadiness.cbam || {};
  const agentOrchestration = (track?.agentOrchestration || {}) as {
    lastRuns?: Record<string, OrchestrationRunSummary>;
  };
  const lastReportingRun = agentOrchestration.lastRuns?.reporting_readiness || null;
  const exportOverallScore = exportModuleScores.cbam ?? exportModuleScores.productPcf ?? null;
  const cbamRegistryFormat = REPORTING_EXPORT_FORMATS.cbam.find((format) => format.id === 'registry');
  const exportGapClosure = (track?.exportGapClosure || {}) as Record<string, unknown>;
  const eudrPlots = (exportProfile.eudrSupplierPlots as Array<Record<string, unknown>>) || [];
  const eudrGap = (exportGapClosure.eudr || {}) as { plotRegistry?: Record<string, unknown> };

  const handleCbamRegistryDownload = async () => {
    if (!cbamRegistryFormat) {
      return;
    }
    const readinessLevel = cbamReadinessSnapshot.reportReadinessLevel || 'prep_draft';
    if (!isExportFormatClientAllowed(cbamRegistryFormat, readinessLevel)) {
      setCbamRegistryFeedback('CBAM registry CSV requires filing-ready status. Run CBAM readiness check first.');
      return;
    }

    setCbamRegistryDownloading(true);
    setCbamRegistryFeedback(null);
    try {
      const { blob, fileName } = await ApiService.exportReportArtifact({
        reportType: 'cbam',
        format: cbamRegistryFormat.apiFormat,
        dateRange: mapReportingDateRange('cbam', '3months'),
      });
      const blobUrl = window.URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = blobUrl;
      anchor.download = fileName || `CBAM_registry_${new Date().toISOString().slice(0, 10)}.csv`;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      window.URL.revokeObjectURL(blobUrl);
      setCbamRegistryFeedback('CBAM registry CSV downloaded.');
    } catch (e) {
      setCbamRegistryFeedback(e instanceof Error ? e.message : 'Failed to download CBAM registry CSV.');
    } finally {
      setCbamRegistryDownloading(false);
    }
  };

  const handleCbamDocumentationAction = async (
    item: { id?: string; field?: string; title?: string },
    confirmed: boolean
  ) => {
    const documentationId = item.id || item.field || '';
    if (!documentationId) return;
    setCbamVerificationBusyId(documentationId);
    try {
      await ApiService.confirmCbamDocumentation({
        documentationId,
        confirmed,
        note: confirmed ? 'Confirmed in Export Hub CBAM section.' : 'Flagged for correction in Export Hub.'
      });
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to update CBAM documentation verification');
    } finally {
      setCbamVerificationBusyId(null);
    }
  };

  const saveExportProfile = async () => {
    setSaving(true);
    try {
      await ApiService.updateComplianceExportProfile(exportProfile);
      await load();
    } finally {
      setSaving(false);
    }
  };

  const loadExportPack = async (framework: string) => {
    const res = await ApiService.getComplianceExportPack(framework, { period });
    setExportPack((res as { data?: unknown })?.data ?? null);
  };

  const renderSection = () => {
    if (loading && !track) {
    return (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress />
      </Box>
    );
  }

    if (!track) {
      return null;
    }

    switch (section) {
      case 'cbam': {
        const cbamExporter = (modules.cbamExporter || {}) as {
          documentationVerification?: {
            documentationVerifications?: Array<{
              id?: string;
              title?: string;
              status?: string;
              reason?: string;
              requiredBillTypes?: string[];
              owner?: string;
            }>;
            verificationRequired?: Array<{
              id?: string;
              field?: string;
              title?: string;
              message?: string;
              requiredBillTypes?: string[];
              owner?: string;
            }>;
            readinessScore?: number;
            tier1InstallationStatus?: { derived?: boolean; totalKgCo2e?: number };
            installationBoundaryStatus?: {
              verified?: boolean;
              tier1BoundaryReady?: boolean;
              proximityKm?: number | null;
              bestMatch?: { reason?: string; documentId?: string };
              referenceSource?: string;
            };
            installationBoundaryVerification?: {
              installationBoundaryStatus?: {
                verified?: boolean;
                tier1BoundaryReady?: boolean;
                proximityKm?: number | null;
                bestMatch?: { reason?: string; documentId?: string };
              };
            };
          };
        };
        const cbamDocVerification = cbamExporter.documentationVerification;
        const cbamDocItems = cbamDocVerification?.verificationRequired || [];
        const cbamDocStatuses = cbamDocVerification?.documentationVerifications || [];
        const installationBoundaryStatus =
          cbamDocVerification?.installationBoundaryStatus
          || cbamDocVerification?.installationBoundaryVerification?.installationBoundaryStatus
          || null;

  return (
          <Stack spacing={2}>
            <Card variant="outlined" sx={{ mb: 3 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  {resolveHubSectionLabel('exportProfile', locale, 'Export profile')}
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="Primary export regions (comma-separated)"
                      fullWidth
                      value={(exportProfile.primaryRegions as string[])?.join(', ') || ''}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          primaryRegions: e.target.value.split(',').map((s) => s.trim()).filter(Boolean),
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth>
                      <InputLabel>CBAM goods</InputLabel>
                      <Select
                        multiple
                        label="CBAM goods"
                        value={(exportProfile.cbamGoodsCategories as string[]) || []}
                        onChange={(e) =>
                          setExportProfile({
                            ...exportProfile,
                            cbamGoodsCategories:
                              typeof e.target.value === 'string'
                                ? e.target.value.split(',')
                                : e.target.value,
                          })
                        }
                        renderValue={(selected) => (selected as string[]).join(', ')}
                      >
                        {CBAM_CATEGORIES.map((cat) => (
                          <MenuItem key={cat} value={cat}>
                            {cat.replace(/_/g, ' ')}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="EU importer EORI (CBAM)"
                      fullWidth
                      value={(exportProfile.euImporterEori as string) || ''}
                      onChange={(e) =>
                        setExportProfile({ ...exportProfile, euImporterEori: e.target.value.trim() })
                      }
                      helperText="Required on CBAM declaration for EU importer identification."
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label={resolveTrackItemLabel('euOperatorId', locale, 'EU operator ID')}
                      fullWidth
                      value={(exportProfile.euOperatorId as string) || ''}
                      onChange={(e) =>
                        setExportProfile({ ...exportProfile, euOperatorId: e.target.value.trim() })
                      }
                      helperText="Installation operator ID for CBAM Transitional Registry — required for filing-ready exports."
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label={resolveTrackItemLabel('euInstallationId', locale, 'EU installation ID')}
                      fullWidth
                      value={(exportProfile.euInstallationId as string) || ''}
                      onChange={(e) =>
                        setExportProfile({ ...exportProfile, euInstallationId: e.target.value.trim() })
                      }
                      helperText="Separate from Indian GST. Do not use GST as the EU installation ID."
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <Typography variant="subtitle1">Information the EU importing company needs</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                      When you export CBAM goods, the EU importer files the declaration. Record the importer identity, your installation, the production route, the electricity source for indirect emissions, and whether a carbon price was due in India. Leave the carbon price amount blank unless your company actually paid one.
                    </Typography>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="EU importer legal name"
                      fullWidth
                      value={String((exportProfile.cbamImporterProvisions as { importerLegalName?: string } | undefined)?.importerLegalName || '')}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          cbamImporterProvisions: {
                            ...((exportProfile.cbamImporterProvisions as object) || {}),
                            importerLegalName: e.target.value,
                          },
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth>
                      <InputLabel>Member State of importation</InputLabel>
                      <Select
                        label="Member State of importation"
                        value={String((exportProfile.cbamImporterProvisions as { importerMemberState?: string } | undefined)?.importerMemberState || '')}
                        onChange={(e) =>
                          setExportProfile({
                            ...exportProfile,
                            cbamImporterProvisions: {
                              ...((exportProfile.cbamImporterProvisions as object) || {}),
                              importerMemberState: e.target.value,
                            },
                          })
                        }
                      >
                        {EU_MEMBER_STATES.map((state) => (
                          <MenuItem key={state} value={state}>{state}</MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="EU importer contact email"
                      fullWidth
                      type="email"
                      value={String((exportProfile.cbamImporterProvisions as { importerContactEmail?: string } | undefined)?.importerContactEmail || '')}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          cbamImporterProvisions: {
                            ...((exportProfile.cbamImporterProvisions as object) || {}),
                            importerContactEmail: e.target.value,
                          },
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="Installation name"
                      fullWidth
                      value={String((exportProfile.cbamImporterProvisions as { installationName?: string } | undefined)?.installationName || '')}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          cbamImporterProvisions: {
                            ...((exportProfile.cbamImporterProvisions as object) || {}),
                            installationName: e.target.value,
                          },
                        })
                      }
                      helperText="Plant name the EU importer will cite."
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      label="Installation address"
                      fullWidth
                      value={String((exportProfile.cbamImporterProvisions as { installationStreetAddress?: string } | undefined)?.installationStreetAddress || '')}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          cbamImporterProvisions: {
                            ...((exportProfile.cbamImporterProvisions as object) || {}),
                            installationStreetAddress: e.target.value,
                          },
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="Operator contact name"
                      fullWidth
                      value={String((exportProfile.cbamImporterProvisions as { operatorContactName?: string } | undefined)?.operatorContactName || '')}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          cbamImporterProvisions: {
                            ...((exportProfile.cbamImporterProvisions as object) || {}),
                            operatorContactName: e.target.value,
                          },
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <TextField
                      label="Operator contact email"
                      fullWidth
                      type="email"
                      value={String((exportProfile.cbamImporterProvisions as { operatorContactEmail?: string } | undefined)?.operatorContactEmail || '')}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          cbamImporterProvisions: {
                            ...((exportProfile.cbamImporterProvisions as object) || {}),
                            operatorContactEmail: e.target.value,
                          },
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      label="Production route"
                      fullWidth
                      value={String((exportProfile.cbamImporterProvisions as { productionRoute?: string } | undefined)?.productionRoute || '')}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          cbamImporterProvisions: {
                            ...((exportProfile.cbamImporterProvisions as object) || {}),
                            productionRoute: e.target.value,
                          },
                        })
                      }
                      helperText="How these goods are made, in your own words. Example: electric arc furnace using purchased scrap."
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      label="Electricity source for indirect emissions"
                      fullWidth
                      value={String((exportProfile.cbamImporterProvisions as { electricitySourceStatement?: string } | undefined)?.electricitySourceStatement || '')}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          cbamImporterProvisions: {
                            ...((exportProfile.cbamImporterProvisions as object) || {}),
                            electricitySourceStatement: e.target.value,
                          },
                        })
                      }
                      helperText="State the source, such as the state grid or a power purchase agreement. Enter a kgCO2e/kWh factor only if you already use a published figure."
                    />
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <FormControl fullWidth>
                      <InputLabel>Carbon price in country of origin</InputLabel>
                      <Select
                        label="Carbon price in country of origin"
                        value={String((exportProfile.cbamImporterProvisions as { carbonPriceDue?: string } | undefined)?.carbonPriceDue || 'not_stated')}
                        onChange={(e) =>
                          setExportProfile({
                            ...exportProfile,
                            cbamImporterProvisions: {
                              ...((exportProfile.cbamImporterProvisions as object) || {}),
                              carbonPriceDue: e.target.value,
                            },
                          })
                        }
                      >
                        <MenuItem value="not_stated">Not stated yet</MenuItem>
                        <MenuItem value="none">No carbon price due</MenuItem>
                        <MenuItem value="paid">Carbon price paid</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                  {String((exportProfile.cbamImporterProvisions as { carbonPriceDue?: string } | undefined)?.carbonPriceDue) === 'paid' ? (
                    <>
                      <Grid item xs={12} md={4}>
                        <TextField
                          label="Carbon price scheme"
                          fullWidth
                          value={String((exportProfile.cbamImporterProvisions as { carbonPriceScheme?: string } | undefined)?.carbonPriceScheme || '')}
                          onChange={(e) =>
                            setExportProfile({
                              ...exportProfile,
                              cbamImporterProvisions: {
                                ...((exportProfile.cbamImporterProvisions as object) || {}),
                                carbonPriceScheme: e.target.value,
                              },
                            })
                          }
                        />
                      </Grid>
                      <Grid item xs={12} md={2}>
                        <TextField
                          label="Amount per tCO2e"
                          fullWidth
                          type="number"
                          value={String((exportProfile.cbamImporterProvisions as { carbonPriceAmountPerTonneCo2e?: number | null } | undefined)?.carbonPriceAmountPerTonneCo2e ?? '')}
                          onChange={(e) =>
                            setExportProfile({
                              ...exportProfile,
                              cbamImporterProvisions: {
                                ...((exportProfile.cbamImporterProvisions as object) || {}),
                                carbonPriceAmountPerTonneCo2e: e.target.value === '' ? null : Number(e.target.value),
                              },
                            })
                          }
                        />
                      </Grid>
                      <Grid item xs={12} md={2}>
                        <TextField
                          label="Currency"
                          fullWidth
                          value={String((exportProfile.cbamImporterProvisions as { carbonPriceCurrency?: string } | undefined)?.carbonPriceCurrency || '')}
                          onChange={(e) =>
                            setExportProfile({
                              ...exportProfile,
                              cbamImporterProvisions: {
                                ...((exportProfile.cbamImporterProvisions as object) || {}),
                                carbonPriceCurrency: e.target.value,
                              },
                            })
                          }
                        />
                      </Grid>
                    </>
                  ) : null}
                  <Grid item xs={12}>
                    <TextField
                      label="Precursors the importer should know about (optional)"
                      fullWidth
                      value={String((exportProfile.cbamImporterProvisions as { precursorNote?: string } | undefined)?.precursorNote || '')}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          cbamImporterProvisions: {
                            ...((exportProfile.cbamImporterProvisions as object) || {}),
                            precursorNote: e.target.value,
                          },
                        })
                      }
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={Boolean(exportProfile.eudrApplicable)}
                          onChange={(e) =>
                            setExportProfile({ ...exportProfile, eudrApplicable: e.target.checked })
                          }
                        />
                      }
                      label="EUDR applies (agri/forest commodities to EU)"
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      label="TCFD physical risks (comma-separated — confirm site-specific risks)"
                      fullWidth
                      multiline
                      minRows={2}
                      value={(exportProfile.tcfdPhysicalRisks as string[])?.join(', ') || ''}
                      onChange={(e) =>
                        setExportProfile({
                          ...exportProfile,
                          tcfdPhysicalRisks: e.target.value.split(',').map((s) => s.trim()).filter(Boolean),
                        })
                      }
                      helperText="Leave blank to use sector defaults (flagged for verification in TCFD pack)."
                    />
                  </Grid>
                </Grid>
                <Button sx={{ mt: 2 }} variant="contained" onClick={saveExportProfile} disabled={saving}>
                  Save export profile
                </Button>
          </CardContent>
        </Card>
            <ComplianceOrchestrationHub
              period={period}
              exportApplicable
              exportScore={exportOverallScore}
              onComplete={() => void load()}
              variant="compact"
              lastRun={lastReportingRun}
            />
            <ReportFilingReadinessBanner
              framework="CBAM"
              readinessLevel={cbamReadinessSnapshot.reportReadinessLevel}
              readinessLabel={cbamReadinessSnapshot.reportReadinessLabel}
              readinessType={cbamReadinessSnapshot.readinessType || 'cbam_registry'}
              filingDisclaimer={cbamReadinessSnapshot.filingDisclaimer}
              blockedReasons={cbamReadinessSnapshot.blockedReasons || []}
              variant={
                cbamReadinessSnapshot.reportReadinessLevel === 'filing_ready' ? 'info' : 'warning'
              }
              period={period}
              onResolved={() => void load()}
            />
            <ComplianceReadinessGapPanel
              moduleGapDetails={moduleGapDetails}
              moduleKeys={['cbam', 'productPcf']}
              title={resolveHubSectionLabel('cbamProductGaps', locale, 'CBAM & product footprint gaps')}
              period={period}
              onResolved={() => void load()}
            />
            {cbamRegistryFeedback ? <Alert severity="info">{cbamRegistryFeedback}</Alert> : null}
            <Stack direction="row" spacing={1} flexWrap="wrap">
              <Button component={RouterLink} to={reportingTabHref('cbam')} variant="outlined">
                Open CBAM quarterly report
              </Button>
              <Button
                variant="outlined"
                disabled={
                  cbamRegistryDownloading
                  || !cbamRegistryFormat
                  || !isExportFormatClientAllowed(
                    cbamRegistryFormat,
                    cbamReadinessSnapshot.reportReadinessLevel
                  )
                }
                onClick={() => void handleCbamRegistryDownload()}
              >
                {cbamRegistryDownloading ? 'Preparing registry CSV…' : 'Download CBAM registry CSV'}
              </Button>
            </Stack>
            <CbamInstallationGpsCapture
              period={period}
              installationBoundaryStatus={installationBoundaryStatus}
              onComplete={() => void load()}
            />
            <ComplianceReadinessGrid
              locale={locale}
              items={[{ key: 'cbam', label: resolveTrackItemLabel('cbam', locale, 'CBAM readiness'), status: readiness.cbam }]}
            />
            {cbamDocVerification ? (
              <Card variant="outlined">
          <CardContent>
                  <Typography variant="subtitle2" gutterBottom>
                    CBAM documentation checklist
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                    Score: {cbamDocVerification.readinessScore ?? 0}%
                    {cbamDocVerification.tier1InstallationStatus?.derived
                      ? ` · Tier 1 path: ${cbamDocVerification.tier1InstallationStatus.totalKgCo2e ?? 0} kg CO₂e`
                      : ' · Tier 1 path: pending verified energy/fuel bills'}
                  </Typography>
                  <Stack spacing={1.5}>
                    {cbamDocStatuses.map((item) => (
                      <Box key={item.id}>
                        <Chip
                          size="small"
                          label={item.status === 'verified_internal' ? 'Verified' : item.status || 'pending'}
                          color={item.status === 'verified_internal' ? 'success' : item.status === 'needs_review' ? 'warning' : 'default'}
                          sx={{ mr: 1 }}
                        />
                        <Typography variant="body2" component="span" fontWeight={600}>
                          {item.title}
                        </Typography>
                        <Typography variant="body2" color="text.secondary" display="block">
                          {item.reason}
                        </Typography>
                        {item.requiredBillTypes?.length ? (
                          <Typography variant="caption" color="text.secondary" display="block">
                            Bills: {item.requiredBillTypes.join(', ')}
                          </Typography>
                        ) : null}
                      </Box>
                    ))}
                  </Stack>
                  {cbamDocItems.length > 0 ? (
                    <Stack spacing={1.5} sx={{ mt: 2 }}>
                      <Typography variant="subtitle2">Confirm or fix</Typography>
                      {cbamDocItems.map((item) => {
                        const docId = item.id || item.field || '';
                        const busy = cbamVerificationBusyId === docId;
                        return (
                          <Box
                            key={docId}
                            sx={{
                              display: 'flex',
                              flexWrap: 'wrap',
                              alignItems: 'center',
                              gap: 1,
                              justifyContent: 'space-between'
                            }}
                          >
                            <Box sx={{ flex: 1, minWidth: 220 }}>
                              <Typography variant="body2" fontWeight={600}>{item.title}</Typography>
                              <Typography variant="body2">{item.message}</Typography>
                            </Box>
                            <Stack direction="row" spacing={1}>
                              <Button
                                size="small"
                                variant="contained"
                                disabled={busy}
                                onClick={() => handleCbamDocumentationAction(item, true)}
                              >
                                Confirm
                              </Button>
                              <Button
                                size="small"
                                variant="outlined"
                                color="warning"
                                disabled={busy}
                                onClick={() => handleCbamDocumentationAction(item, false)}
                              >
                                Fix
                              </Button>
                            </Stack>
                          </Box>
                        );
                      })}
                    </Stack>
                  ) : null}
          </CardContent>
        </Card>
            ) : null}
            <CbamExportReadinessPanel showHydrogen />
            <ComplianceGapWorkspace period={period} defaultTab="cbam" showCbam />
            <ComplianceJsonPanel
              title={resolveHubSectionLabel('cbamExporterPack', locale, 'CBAM exporter pack')}
              data={modules.cbamExporter}
              filename="cbam-exporter-pack.json"
            />
          </Stack>
        );
      }
      case 'product-pcf':
        return <ProductPcfWorkspace />;
      case 'csrd-supplier':
        return (
          <Stack spacing={2}>
            <BuyerPackReadinessPanel
              framework="csrd"
              frameworkLabel="CSRD / ESRS"
              packValidation={packValidation.csrdSupplier}
              questionnaires={buyerPackReadiness?.questionnaires}
              supplierQuestionnaires={supplierQuestionnaires}
              period={period}
              onRefresh={() => void load()}
            />
            <Button variant="outlined" onClick={() => loadExportPack('csrd')}>
              Refresh CSRD pack
            </Button>
            <EsrsEnvironmentalTopicsPanel
              exportProfile={exportProfile as never}
              onSaved={() => void load()}
            />
            <ComplianceJsonPanel
              title={resolveHubSectionLabel('csrdSupplier', locale, 'CSRD / ESRS supplier datapoints')}
              data={exportPack || modules.csrdSupplier}
              filename="csrd-supplier-pack.json"
            />
          </Stack>
        );
      case 'cdp': {
        const cdpPack = (exportPack || modules.cdpClimate || {}) as {
          sectionsIncluded?: string[];
          c1?: Record<string, unknown>;
          c7?: { scope1?: number; scope2?: number; scope3?: number };
        };
        const sections = cdpPack.sectionsIncluded || [];
        return (
          <Stack spacing={2}>
            <BuyerPackReadinessPanel
              framework="cdp"
              frameworkLabel="CDP Climate"
              packValidation={packValidation.cdpClimate}
              questionnaires={buyerPackReadiness?.questionnaires}
              supplierQuestionnaires={supplierQuestionnaires}
              period={period}
              onRefresh={() => void load()}
            />
            <Alert severity={sections.length >= 15 ? 'success' : 'info'}>
              CDP Climate Change questionnaire: {sections.length || 0}/15 sections mapped (C1–C15).
              {sections.length >= 15
                ? ' Pack ready for buyer portal upload preparation.'
                : ' Complete missing sections before CDP submission.'}
            </Alert>
            <Button variant="outlined" onClick={() => loadExportPack('cdp')}>
              Refresh CDP mapping
            </Button>
            <ComplianceJsonPanel
              title={resolveHubSectionLabel('cdpClimate', locale, 'CDP Climate Change mapping (C1–C15)')}
              data={exportPack || modules.cdpClimate}
              filename="cdp-climate-pack.json"
            />
          </Stack>
        );
      }
      case 'gri':
        return (
          <Stack spacing={2}>
            <BuyerPackReadinessPanel
              framework="gri"
              frameworkLabel="GRI 305"
              packValidation={packValidation.griStandards}
              questionnaires={buyerPackReadiness?.questionnaires}
              supplierQuestionnaires={supplierQuestionnaires}
              period={period}
              onRefresh={() => void load()}
            />
            <Button variant="outlined" onClick={() => loadExportPack('gri')}>
              Refresh GRI 305 pack
            </Button>
            <ComplianceJsonPanel
              title={resolveHubSectionLabel('gri305', locale, 'GRI Standards (305 emissions)')}
              data={exportPack || modules.griStandards}
              filename="gri-305-emissions-pack.json"
            />
          </Stack>
        );
      case 'tcfd-issb':
        return (
          <Stack spacing={2}>
            <BuyerPackReadinessPanel
              framework="tcfd"
              frameworkLabel="TCFD / IFRS S2"
              packValidation={packValidation.tcfdIssb}
              questionnaires={buyerPackReadiness?.questionnaires}
              supplierQuestionnaires={supplierQuestionnaires}
              period={period}
              onRefresh={() => void load()}
            />
            <Button variant="outlined" onClick={() => loadExportPack('tcfd')}>
              Refresh TCFD / ISSB pack
            </Button>
            <ComplianceJsonPanel
              title={resolveHubSectionLabel('tcfdIssb', locale, 'TCFD / IFRS S2 structure')}
              data={exportPack || modules.tcfdIssb}
              filename="tcfd-issb-pack.json"
            />
          </Stack>
        );
      case 'eudr':
        return (
          <Stack spacing={2}>
            <EudrPlotRegistryPanel
              plots={eudrPlots as never}
              ddsReference={(exportProfile.eudrDdsReference as string) || ''}
              eudrApplicable={Boolean(exportProfile.eudrApplicable)}
              plotRegistry={eudrGap.plotRegistry as never}
              onSaved={() => void load()}
            />
            <GpsGeotaggedCapture
              workflow="eudr_plot_evidence"
              period={period}
              onComplete={() => void load()}
            />
            <ComplianceJsonPanel
              title={resolveHubSectionLabel('eudrSkeleton', locale, 'EUDR due diligence skeleton')}
              data={modules.eudr}
              filename="eudr-pack.json"
            />
          </Stack>
        );
      case 'ecovadis':
        return (
          <Stack spacing={2}>
            <BuyerPackReadinessPanel
              framework="ecovadis"
              frameworkLabel="EcoVadis"
              packValidation={packValidation.ecovadis}
              questionnaires={buyerPackReadiness?.questionnaires}
              supplierQuestionnaires={supplierQuestionnaires}
              period={period}
              onRefresh={() => void load()}
            />
            <Button variant="outlined" onClick={() => loadExportPack('ecovadis')}>
              Refresh EcoVadis pack
            </Button>
            <EcovadisAssessmentPanel
              ecovadis={(modules.ecovadis || exportPack) as Record<string, unknown>}
              onSaved={() => void load()}
            />
            <ComplianceJsonPanel
              title={resolveHubSectionLabel('ecovadisDatapoints', locale, 'EcoVadis-aligned datapoints')}
              data={exportPack || modules.ecovadis}
              filename="ecovadis-pack.json"
            />
          </Stack>
        );
      default:
        return null;
    }
  };

  const rawSection = (searchParams.get('section') || '').trim().toLowerCase();
  const retiredHref = rawSection === 'overview'
    ? location.pathname
    : EXPORT_RETIRED_SECTION_HREFS[rawSection];
  if (retiredHref) {
    return <Navigate to={retiredHref} replace />;
  }

  return (
    <ComplianceTrackShell
      trackTitle={isEnterprise ? 'Global buyer disclosure' : 'Global export compliance'}
      trackDescription={
        isEnterprise
          ? 'CDP C1–C15, CSRD value-chain datapoints, TCFD/ISSB S2, and buyer questionnaire packs for listed and large enterprises.'
          : 'Requirements for Indian exporters: EU CBAM, product PCF, CSRD value-chain datapoints, CDP, TCFD/ISSB S2, EUDR, and EcoVadis.'
      }
      trackPath={isEnterprise ? '/enterprise/compliance' : '/compliance/export'}
      sectionGroups={EXPORT_COMPLIANCE_GROUPS}
      activeSection={section}
      onSectionChange={setSection}
      period={period}
      onPeriodChange={setPeriod}
      loading={loading}
    >
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}
      {renderSection()}
    </ComplianceTrackShell>
  );
};

export default ExportComplianceTrack;
