import React from 'react';
import GpsGeotaggedCapture from './GpsGeotaggedCapture';

type InstallationBoundaryStatus = {
  verified?: boolean;
  tier1BoundaryReady?: boolean;
  proximityKm?: number | null;
  bestMatch?: {
    reason?: string;
    documentId?: string;
  };
};

type CbamInstallationGpsCaptureProps = {
  period?: string;
  installationBoundaryStatus?: InstallationBoundaryStatus | null;
  onComplete?: () => void;
};

const CbamInstallationGpsCapture: React.FC<CbamInstallationGpsCaptureProps> = ({
  period = 'annual',
  installationBoundaryStatus,
  onComplete,
}) => {
  const statusChip = installationBoundaryStatus?.verified
    ? { label: 'Boundary verified', color: 'success' as const }
    : installationBoundaryStatus?.tier1BoundaryReady
      ? { label: 'Evidence detected — review pending', color: 'warning' as const }
      : { label: 'Site photo required', color: 'default' as const };

  const statusDetail = installationBoundaryStatus?.bestMatch?.reason
    ? `Latest check: ${installationBoundaryStatus.bestMatch.reason}${
      installationBoundaryStatus.proximityKm != null
        ? ` (${installationBoundaryStatus.proximityKm.toFixed(2)} km from reference)`
        : ''
    }`
    : null;

  return (
    <GpsGeotaggedCapture
      workflow="cbam_installation_boundary"
      period={period}
      statusChip={statusChip}
      statusDetail={statusDetail}
      onComplete={onComplete}
    />
  );
};

export default CbamInstallationGpsCapture;
