import React, { useEffect, useState } from 'react';
import {
  Alert,
  Button,
  Card,
  CardContent,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';
import { COMPLIANCE_PANEL_STRINGS } from '../../i18n/compliancePanelLocale';

type EsrsEnvironmentalTopicsPanelProps = {
  exportProfile?: {
    esrsE1EnergyNote?: string;
    esrsE2PollutionNote?: string;
    esrsE3WaterNote?: string;
    esrsE4BiodiversityNote?: string;
    esrsE5ResourcesNote?: string;
  };
  locale?: 'en' | 'hi';
  onSaved?: () => void;
};

const EsrsEnvironmentalTopicsPanel: React.FC<EsrsEnvironmentalTopicsPanelProps> = ({
  exportProfile = {},
  locale = 'en',
  onSaved,
}) => {
  const strings = COMPLIANCE_PANEL_STRINGS[locale];
  const [e1Note, setE1Note] = useState(exportProfile.esrsE1EnergyNote || '');
  const [e2Note, setE2Note] = useState(exportProfile.esrsE2PollutionNote || '');
  const [e3Note, setE3Note] = useState(exportProfile.esrsE3WaterNote || '');
  const [e4Note, setE4Note] = useState(exportProfile.esrsE4BiodiversityNote || '');
  const [e5Note, setE5Note] = useState(exportProfile.esrsE5ResourcesNote || '');
  const [saving, setSaving] = useState(false);
  const [feedback, setFeedback] = useState<{ severity: 'success' | 'error'; message: string } | null>(null);

  useEffect(() => {
    setE1Note(exportProfile.esrsE1EnergyNote || '');
    setE2Note(exportProfile.esrsE2PollutionNote || '');
    setE3Note(exportProfile.esrsE3WaterNote || '');
    setE4Note(exportProfile.esrsE4BiodiversityNote || '');
    setE5Note(exportProfile.esrsE5ResourcesNote || '');
  }, [
    exportProfile.esrsE1EnergyNote,
    exportProfile.esrsE2PollutionNote,
    exportProfile.esrsE3WaterNote,
    exportProfile.esrsE4BiodiversityNote,
    exportProfile.esrsE5ResourcesNote,
  ]);

  const save = async () => {
    setSaving(true);
    setFeedback(null);
    try {
      await ApiService.updateComplianceExportProfile({
        esrsE1EnergyNote: e1Note.trim() || undefined,
        esrsE2PollutionNote: e2Note.trim() || undefined,
        esrsE3WaterNote: e3Note.trim() || undefined,
        esrsE4BiodiversityNote: e4Note.trim() || undefined,
        esrsE5ResourcesNote: e5Note.trim() || undefined,
      });
      setFeedback({ severity: 'success', message: strings.esrsSaveSuccess });
      onSaved?.();
    } catch (e) {
      setFeedback({ severity: 'error', message: e instanceof Error ? e.message : strings.esrsSaveFailed });
    } finally {
      setSaving(false);
    }
  };

  return (
    <Card variant="outlined">
      <CardContent>
        <Typography variant="subtitle1" gutterBottom>{strings.esrsTitle}</Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          {strings.esrsSubtitle}
        </Typography>
        {feedback ? <Alert severity={feedback.severity} sx={{ mb: 2 }}>{feedback.message}</Alert> : null}
        <Stack spacing={2}>
          <TextField
            label={strings.esrsE1Label}
            fullWidth
            multiline
            minRows={2}
            value={e1Note}
            onChange={(e) => setE1Note(e.target.value)}
            helperText={strings.esrsE1Helper}
          />
          <TextField
            label={strings.esrsE2Label}
            fullWidth
            multiline
            minRows={2}
            value={e2Note}
            onChange={(e) => setE2Note(e.target.value)}
            helperText={strings.esrsE2Helper}
          />
          <TextField
            label={strings.esrsE3Label}
            fullWidth
            multiline
            minRows={2}
            value={e3Note}
            onChange={(e) => setE3Note(e.target.value)}
            helperText={strings.esrsE3Helper}
          />
          <TextField
            label={strings.esrsE4Label}
            fullWidth
            multiline
            minRows={2}
            value={e4Note}
            onChange={(e) => setE4Note(e.target.value)}
            helperText={strings.esrsE4Helper}
          />
          <TextField
            label={strings.esrsE5Label}
            fullWidth
            multiline
            minRows={2}
            value={e5Note}
            onChange={(e) => setE5Note(e.target.value)}
            helperText={strings.esrsE5Helper}
          />
          <Button variant="contained" onClick={() => void save()} disabled={saving}>
            {strings.esrsSaveButton}
          </Button>
        </Stack>
      </CardContent>
    </Card>
  );
};

export default EsrsEnvironmentalTopicsPanel;
