export const formatCompliancePanelString = (
  template: string,
  vars: Record<string, string | number>
): string =>
  Object.entries(vars).reduce(
    (text, [key, value]) => text.replace(new RegExp(`\\{${key}\\}`, 'g'), String(value)),
    template
  );
