import React, { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography
} from '@mui/material';
import api from '../../services/api';
import GreenHydrogenRoutePanel from './GreenHydrogenRoutePanel';
import { MODULE_CHECK_LABELS } from '../../constants/orchestrationUxLabels';
import { useCbamReportQuery, invalidateReportingReadinessCaches } from '../../hooks/queries/useReportingQueries';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';

type Shipment = {
  shipmentId?: string;
  destination?: string;
  goodsCategory?: string;
  volumeTonnes?: number;
  embeddedEmissionsTco2e?: number;
  supplyChainGap?: string | null;
};

type CbamReportPayload = {
  shipments?: Shipment[];
  supplyChainGaps?: string[];
  supplyChainRegistry?: {
    registryDepthScore?: number;
    precursorSupplierCount?: number;
    tier1SubmissionCount?: number;
    tier1SharePct?: number;
  };
};

export default function CbamExportReadinessPanel({
  showHydrogen = false,
  eager = false
}: {
  showHydrogen?: boolean;
  /** When false (default), wait for user click before CBAM report + H2 fetches. */
  eager?: boolean;
}) {
  const queryClient = useQueryClient();
  const [expanded, setExpanded] = useState(eager);
  const cbamReportQuery = useCbamReportQuery<CbamReportPayload>('quarter', expanded);
  const [draftLoading, setDraftLoading] = useState(false);
  const [orchestrating, setOrchestrating] = useState(false);
  const [message, setMessage] = useState('');

  const shipments = cbamReportQuery.data?.shipments || [];
  const gaps = cbamReportQuery.data?.supplyChainGaps || [];
  const registry = cbamReportQuery.data?.supplyChainRegistry;
  const loading = expanded && cbamReportQuery.isLoading;

  const refreshCbamReport = async () => {
    invalidateReportingReadinessCaches(queryClient, 'annual');
    await queryClient.invalidateQueries({ queryKey: ['reporting', 'cbam'] });
    await cbamReportQuery.refetch();
  };

  const runCbamOrchestration = async () => {
    setOrchestrating(true);
    setMessage('');
    try {
      const res = await api.orchestrateCbamReadiness({ period: 'annual', applyChanges: true });
      if (res.success) {
        const score = res.data?.overallReadinessScore ?? res.overallReadinessScore;
        setMessage(
          score != null
            ? `CBAM readiness orchestration complete — score ${score}%. Shipments and Tier-1 evidence updated where possible.`
            : 'CBAM readiness orchestration complete.'
        );
        await refreshCbamReport();
      }
    } catch {
      setMessage('CBAM orchestration could not complete — check export profile and upload metered bills.');
    } finally {
      setOrchestrating(false);
    }
  };

  const downloadDeclaration = async () => {
    setDraftLoading(true);
    try {
      const res = await api.getCbamDeclarationDraft({ period: 'quarter' });
      if (res.success) {
        setMessage('EU CBAM declaration draft loaded — use Reporting → CBAM for full export workflow.');
      }
    } finally {
      setDraftLoading(false);
    }
  };

  if (!expanded) {
    return (
      <Card variant="outlined">
        <CardContent>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }} justifyContent="space-between">
            <Box>
              <Typography variant="subtitle1">CBAM shipment embedded emissions</Typography>
              <Typography variant="body2" color="text.secondary">
                Load quarterly shipment allocation and optional green-hydrogen route scenarios.
              </Typography>
            </Box>
            <Button variant="outlined" onClick={() => setExpanded(true)}>
              Load CBAM detail
            </Button>
          </Stack>
        </CardContent>
      </Card>
    );
  }

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" p={2}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  return (
    <Stack spacing={2}>
      {showHydrogen && <GreenHydrogenRoutePanel />}
      <Card variant="outlined">
        <CardContent>
          <Typography variant="h6" gutterBottom>
            CBAM shipment embedded emissions
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Per-shipment allocation for EU-bound aluminium, steel, and cement exports with supply-chain gap flags.
          </Typography>
          {gaps.length > 0 && (
            <Alert severity="warning" sx={{ mb: 2 }}>
              Supply chain gaps: {gaps.join(' · ')}
            </Alert>
          )}
          {registry ? (
            <Alert severity={registry.registryDepthScore && registry.registryDepthScore >= 70 ? 'success' : 'info'} sx={{ mb: 2 }}>
              Registry depth {registry.registryDepthScore ?? 0}% — {registry.precursorSupplierCount ?? 0} precursor supplier(s),
              {` ${registry.tier1SubmissionCount ?? 0} Tier-1 submission(s), ${registry.tier1SharePct ?? 0}% Tier-1 share.`}
            </Alert>
          ) : null}
          <ScrollableTableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Shipment</TableCell>
                  <TableCell>Good</TableCell>
                  <TableCell align="right">Tonnes</TableCell>
                  <TableCell align="right">Embedded tCO₂e</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {shipments.map((row: Shipment) => (
                  <TableRow key={row.shipmentId}>
                    <TableCell>{row.shipmentId}</TableCell>
                    <TableCell>{row.goodsCategory}</TableCell>
                    <TableCell align="right">{row.volumeTonnes}</TableCell>
                    <TableCell align="right">{row.embeddedEmissionsTco2e}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </ScrollableTableContainer>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ mt: 2 }}>
            <Button
              variant="contained"
              disabled={orchestrating}
              onClick={() => { void runCbamOrchestration(); }}
            >
              {orchestrating ? MODULE_CHECK_LABELS.cbam.running : MODULE_CHECK_LABELS.cbam.button}
            </Button>
            <Button variant="outlined" disabled={draftLoading} onClick={downloadDeclaration}>
              {draftLoading ? 'Loading…' : 'Generate EU CBAM declaration draft'}
            </Button>
          </Stack>
          {message && <Alert severity="success" sx={{ mt: 2 }}>{message}</Alert>}
        </CardContent>
      </Card>
    </Stack>
  );
}
