import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Card,
  CardContent,
  CircularProgress,
  Stack,
  Typography
} from '@mui/material';
import api from '../../services/api';

export default function GreenHydrogenRoutePanel() {
  const [data, setData] = useState<Record<string, unknown> | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.getGreenHydrogenScenarios({ electrolyzerCapacityMw: 50, renewablePpaSharePercent: 85 })
      .then((res) => {
        if (res.success) setData(res.data as Record<string, unknown>);
      })
      .finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" p={2}>
        <CircularProgress size={28} />
      </Box>
    );
  }

  const scenarios = (data?.scenarios as Array<Record<string, unknown>>) || [];
  const recommended = scenarios.find((s) => s.scenarioId === data?.recommendedScenarioId) || scenarios[0];
  const economics = (recommended?.economics || {}) as Record<string, number | boolean>;

  return (
    <Card variant="outlined" sx={{ mb: 2 }}>
      <CardContent>
        <Typography variant="h6" gutterBottom>
          Green hydrogen route optimizer
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Electrolyzer sizing, renewable PPA mix, water requirement, and delivered H₂ cost vs grey hydrogen under NGHM subsidy scenarios.
        </Typography>
        {recommended && (
          <Stack spacing={1}>
            <Typography variant="body2">
              Recommended: <strong>{String((recommended.subsidyScenario as Record<string, string>)?.label || recommended.scenarioId)}</strong>
            </Typography>
            <Typography variant="body2">
              Levelized cost: ₹{economics.levelizedCostInrPerKg}/kg vs grey ₹{economics.greyHydrogenBenchmarkInrPerKg}/kg
              {' '}({economics.competitiveVsGrey ? 'competitive' : `${economics.greyDeltaPercent}% vs grey`})
            </Typography>
            <Typography variant="body2">
              Annual production: {Number(recommended.annualH2ProductionTonnes || 0).toLocaleString('en-IN')} tonnes · Water: {Number(recommended.annualWaterRequirementKl || 0).toLocaleString('en-IN')} kL/yr
            </Typography>
            <Alert severity={economics.competitiveVsGrey ? 'success' : 'warning'}>
              CO₂ intensity: {Number((recommended.emissions as Record<string, number>)?.co2IntensityKgPerKgH2 || 0)} kgCO₂e/kg H₂ — relevant for EU CBAM hydrogen goods category.
            </Alert>
          </Stack>
        )}
      </CardContent>
    </Card>
  );
}
