import React from 'react';
import {
  Box,
  Card,
  CardContent,
  Chip,
  Grid,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { readinessChipColor, readinessLabel } from '../../constants/complianceHub';
import {
  resolveReadinessStatusLabel,
  resolveTrackItemLabel,
} from '../../constants/complianceTrackLocale';
import type { ReadinessLocale } from '../../i18n/readinessLocale';
import PlainLanguageLabel from '../shared/PlainLanguageLabel';
import { TRI_TILE_GRID } from '../../constants/appShellLayout';

const GRID_GLOSSARY_IDS: Record<string, string> = {
  brsr: 'brsr',
  brsrCore: 'brsr',
  iso: 'iso14064',
  isoAssurance: 'iso14064',
  cbam: 'cbam',
  cdp: 'cdp',
  csrd: 'csrd',
  ecovadis: 'ecovadis',
  pat: 'pat',
  sbti: 'ghg',
  zed: 'msme',
  supplierPortal: 'msme',
  productPcf: 'scope3',
};

export type ReadinessGridItem = {
  key: string;
  label: string;
  status?: string;
  score?: number | null;
  href?: string;
  threshold?: number | null;
};

interface ComplianceReadinessGridProps {
  items: ReadinessGridItem[];
  compact?: boolean;
  locale?: ReadinessLocale;
}

const formatScore = (score?: number | null): string | null => {
  if (score == null || !Number.isFinite(Number(score))) {
    return null;
  }
  return `${Math.round(Number(score))}%`;
};

const ComplianceReadinessGrid: React.FC<ComplianceReadinessGridProps> = ({
  items,
  compact = false,
  locale = 'en',
}) => (
  <Grid container spacing={compact ? 1.5 : 2} sx={{ mb: compact ? 0 : 3 }}>
    {items.map((item) => {
      const scoreLabel = formatScore(item.score);
      const scoreValue = item.score != null && Number.isFinite(Number(item.score))
        ? Math.min(100, Math.max(0, Math.round(Number(item.score))))
        : null;
      const displayLabel = resolveTrackItemLabel(item.key, locale, item.label);
      const statusLabel = locale === 'en'
        ? readinessLabel(item.status)
        : resolveReadinessStatusLabel(item.status, locale, readinessLabel(item.status));

      const card = (
        <Card variant="outlined" sx={{ height: '100%' }}>
          <CardContent>
            <Typography variant="subtitle2" color="text.secondary" gutterBottom>
              {GRID_GLOSSARY_IDS[item.key] ? (
                <PlainLanguageLabel termId={GRID_GLOSSARY_IDS[item.key]} variant="heading">
                  {displayLabel}
                </PlainLanguageLabel>
              ) : (
                displayLabel
              )}
            </Typography>
            <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" sx={{ mb: scoreValue != null ? 1 : 0 }}>
              {scoreLabel ? (
                <Typography variant="h5" component="span" fontWeight={700}>
                  {scoreLabel}
                </Typography>
              ) : null}
              <Chip
                size="small"
                label={statusLabel}
                color={readinessChipColor(item.status)}
              />
            </Stack>
            {scoreValue != null ? (
              <Box sx={{ mt: 1 }}>
                <LinearProgress
                  variant="determinate"
                  value={scoreValue}
                  sx={{ height: 6, borderRadius: 3 }}
                />
                {item.threshold != null ? (
                  <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
                    Target: {item.threshold}%
                  </Typography>
                ) : null}
              </Box>
            ) : null}
          </CardContent>
        </Card>
      );

      return (
        <Grid item {...TRI_TILE_GRID} key={item.key}>
          {item.href ? (
            <Box
              component={RouterLink}
              to={item.href}
              sx={{
                textDecoration: 'none',
                color: 'inherit',
                display: 'block',
                borderRadius: '12px',
                '&:hover .MuiCard-root': {
                  borderColor: 'primary.main',
                },
                '&:focus-visible': {
                  outline: '2px solid',
                  outlineColor: 'primary.main',
                  outlineOffset: 2,
                },
              }}
            >
              {card}
            </Box>
          ) : (
            card
          )}
        </Grid>
      );
    })}
  </Grid>
);

export default ComplianceReadinessGrid;
