import React, { useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import ApiService from '../../services/api';
import BuyerPackQuestionnaireWizard, {
  type SupplierQuestionnaireRecord,
} from './BuyerPackQuestionnaireWizard';
import { BuyerQuestionnaireDetail } from './BuyerQuestionnaireGapPanel';

type PackValidation = {
  valid?: boolean;
  missingFields?: string[];
  warnings?: string[];
  framework?: string;
};

type BuyerPackReadinessPanelProps = {
  framework: 'cdp' | 'csrd' | 'gri' | 'tcfd' | 'ecovadis';
  frameworkLabel: string;
  packValidation?: PackValidation | null;
  questionnaires?: BuyerQuestionnaireDetail[];
  supplierQuestionnaires?: SupplierQuestionnaireRecord[];
  period?: string;
  supplierPortalLink?: string;
  onRefresh?: () => void;
};

const FRAMEWORK_ALIASES: Record<string, string[]> = {
  cdp: ['cdp'],
  csrd: ['csrd'],
  gri: ['gri'],
  tcfd: ['tcfd'],
  ecovadis: ['ecovadis'],
};

const humanizeField = (field: string): string =>
  field
    .split('.')
    .pop()
    ?.replace(/([A-Z])/g, ' $1')
    .replace(/_/g, ' ')
    .replace(/^./, (c) => c.toUpperCase())
    .trim() || field;

const BuyerPackReadinessPanel: React.FC<BuyerPackReadinessPanelProps> = ({
  framework,
  frameworkLabel,
  packValidation,
  questionnaires = [],
  supplierQuestionnaires = [],
  period = 'annual',
  supplierPortalLink = '/buyer-audit',
  onRefresh,
}) => {
  const [prefillingAll, setPrefillingAll] = useState(false);
  const [validatingPortal, setValidatingPortal] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const frameworkQuestionnaires = useMemo(
    () => questionnaires.filter((entry) => FRAMEWORK_ALIASES[framework]?.includes(entry.framework)),
    [framework, questionnaires]
  );

  const frameworkRecords = useMemo(
    () => supplierQuestionnaires.filter((entry) => FRAMEWORK_ALIASES[framework]?.includes(entry.framework || '')),
    [framework, supplierQuestionnaires]
  );

  const missingFields = packValidation?.missingFields || [];
  const warnings = packValidation?.warnings || [];
  const packScore = packValidation?.valid
    ? 100
    : Math.max(0, 100 - missingFields.length * 12 - warnings.length * 8);

  const handlePrefillAll = async () => {
    setPrefillingAll(true);
    setError(null);
    setFeedback(null);
    try {
      const res = await ApiService.prefillAllSupplierQuestionnairesFromInventory({ period });
      const message = (res as { message?: string })?.message || 'Questionnaires prefilled from inventory.';
      setFeedback(message);
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Bulk prefill failed');
    } finally {
      setPrefillingAll(false);
    }
  };

  const handleValidatePortal = async () => {
    setValidatingPortal(true);
    setError(null);
    setFeedback(null);
    try {
      const res = await ApiService.validateAllSupplierQuestionnairesPortal({ period });
      const message = (res as { message?: string })?.message || 'Portal validation completed.';
      setFeedback(message);
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Portal validation failed');
    } finally {
      setValidatingPortal(false);
    }
  };

  const portalIssues = frameworkQuestionnaires.flatMap((entry) => entry.portalValidation?.errors || []);
  const portalReadyCount = frameworkQuestionnaires.filter((entry) => entry.portalValidation?.portalReady).length;

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack direction="row" justifyContent="space-between" alignItems="flex-start" flexWrap="wrap" gap={1}>
          <Box>
            <Typography variant="h6" gutterBottom>
              {frameworkLabel} buyer readiness
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Validate pack fields, prefill questionnaire responses, and close gaps before buyer submission.
            </Typography>
          </Box>
          <Stack direction="row" spacing={1} flexWrap="wrap">
            <Chip
              size="small"
              color={packValidation?.valid ? 'success' : 'warning'}
              label={packValidation?.valid ? 'Pack valid' : 'Pack gaps remain'}
            />
            <Chip size="small" label={`${Math.round(packScore)}% pack score`} />
          </Stack>
        </Stack>

        <LinearProgress
          variant="determinate"
          value={Math.min(100, Math.max(0, packScore))}
          sx={{ mt: 2, mb: 1, height: 8, borderRadius: 4 }}
        />

        {error ? <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert> : null}
        {feedback ? <Alert severity="success" sx={{ mt: 2 }}>{feedback}</Alert> : null}

        {(missingFields.length > 0 || warnings.length > 0) ? (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" gutterBottom>
              Pack validation gaps
            </Typography>
            <Stack spacing={0.75}>
              {missingFields.slice(0, 6).map((field) => (
                <Typography key={field} variant="body2" color="text.secondary">
                  • Missing: {humanizeField(field)}
                </Typography>
              ))}
              {warnings.slice(0, 3).map((warning) => (
                <Typography key={warning} variant="body2" color="warning.main">
                  • {warning}
                </Typography>
              ))}
            </Stack>
          </Box>
        ) : (
          <Alert severity="success" sx={{ mt: 2 }}>
            {frameworkLabel} pack passes validation checks.
          </Alert>
        )}

        <Stack direction="row" spacing={1} sx={{ mt: 2 }} flexWrap="wrap">
          <Button size="small" component={RouterLink} to={supplierPortalLink}>
            Open supplier portal
          </Button>
          <Button
            size="small"
            variant="outlined"
            disabled={prefillingAll || frameworkRecords.length === 0}
            onClick={() => void handlePrefillAll()}
          >
            {prefillingAll ? 'Prefilling…' : 'Prefill all questionnaires'}
          </Button>
          <Button
            size="small"
            variant="contained"
            disabled={validatingPortal || frameworkRecords.length === 0}
            onClick={() => void handleValidatePortal()}
          >
            {validatingPortal ? 'Validating…' : 'Validate for portal'}
          </Button>
        </Stack>

        {frameworkQuestionnaires.length > 0 ? (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" gutterBottom>
              Portal validator ({portalReadyCount}/{frameworkQuestionnaires.length} ready)
            </Typography>
            {portalIssues.length > 0 ? (
              <Stack spacing={0.5}>
                {portalIssues.slice(0, 4).map((issue) => (
                  <Typography key={issue} variant="body2" color="error.main">
                    • {issue}
                  </Typography>
                ))}
              </Stack>
            ) : (
              <Typography variant="body2" color="text.secondary">
                Run portal validation to check questionnaire vs pack consistency before buyer upload.
              </Typography>
            )}
          </Box>
        ) : null}

        {frameworkQuestionnaires.length > 0 ? (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" gutterBottom>
              Linked buyer requests ({frameworkQuestionnaires.length})
            </Typography>
            <Stack spacing={0.5}>
              {frameworkQuestionnaires.slice(0, 4).map((entry) => (
                <Typography key={entry.id || entry.buyerName} variant="body2" color="text.secondary">
                  • {entry.buyerName} — {entry.readinessScore}% ready
                  {entry.missingQuestionFields?.length
                    ? ` · ${entry.missingQuestionFields.length} question gap(s)`
                    : ''}
                </Typography>
              ))}
            </Stack>
          </Box>
        ) : (
          <Alert severity="info" sx={{ mt: 2 }}>
            No {frameworkLabel} questionnaires registered yet. Import a template in the supplier portal section.
          </Alert>
        )}

        {frameworkRecords.length > 0 ? (
          <Stack spacing={2} sx={{ mt: 2 }}>
            {frameworkRecords.map((record) => (
              <BuyerPackQuestionnaireWizard
                key={record.id || record._id || record.buyerName}
                questionnaire={record}
                period={period}
                onSaved={onRefresh}
              />
            ))}
          </Stack>
        ) : null}
      </CardContent>
    </Card>
  );
};

export default BuyerPackReadinessPanel;
